begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local s1.tap='on';
select no_plan();
\ir s1_fixture.sql
select pg_temp.check(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity),'all public tables enable RLS');
select pg_temp.check(not exists(select 1 from pg_tables t where t.schemaname='public' and t.tablename not in ('consent_documents','terms_versions','profile_consents','profile_consent_states') and not exists(select 1 from pg_policy p where p.polrelid=('public.'||t.tablename)::regclass and not p.polpermissive and pg_get_expr(p.polqual,p.polrelid) like '%has_current_terms_consent%')),'catalog has restrictive gate for every user table');
select pg_temp.check(not has_table_privilege('authenticated','public.participants','SELECT'),'no whole-table SELECT participants');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','personal_data','SELECT'),'no raw participants.personal_data SELECT');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','personal_data','INSERT'),'no participants.personal_data INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','personal_data','UPDATE'),'no participants.personal_data UPDATE');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','start_location_name','SELECT'),'no raw participants.start_location_name SELECT');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','start_location_name','INSERT'),'no participants.start_location_name INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','start_location_name','UPDATE'),'no participants.start_location_name UPDATE');
