select pg_temp.check(not has_column_privilege('authenticated','public.participants','start_latitude','INSERT'),'no participants.start_latitude INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','start_latitude','UPDATE'),'no participants.start_latitude UPDATE');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','start_longitude','SELECT'),'no raw participants.start_longitude SELECT');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','start_longitude','INSERT'),'no participants.start_longitude INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.participants','start_longitude','UPDATE'),'no participants.start_longitude UPDATE');
select pg_temp.check(not has_table_privilege('authenticated','public.dutch_pay_bills','SELECT'),'no whole-table SELECT dutch_pay_bills');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','bank_name','SELECT'),'no raw dutch_pay_bills.bank_name SELECT');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','bank_name','INSERT'),'no dutch_pay_bills.bank_name INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','bank_name','UPDATE'),'no dutch_pay_bills.bank_name UPDATE');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','account_number','SELECT'),'no raw dutch_pay_bills.account_number SELECT');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','account_number','INSERT'),'no dutch_pay_bills.account_number INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','account_number','UPDATE'),'no dutch_pay_bills.account_number UPDATE');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','account_holder','SELECT'),'no raw dutch_pay_bills.account_holder SELECT');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','account_holder','INSERT'),'no dutch_pay_bills.account_holder INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.dutch_pay_bills','account_holder','UPDATE'),'no dutch_pay_bills.account_holder UPDATE');
select pg_temp.check(not has_table_privilege('authenticated','public.notifications','SELECT'),'no whole-table SELECT notifications');
select pg_temp.check(not has_column_privilege('authenticated','public.notifications','bank_name','SELECT'),'no raw notifications.bank_name SELECT');
select pg_temp.check(not has_column_privilege('authenticated','public.notifications','bank_name','INSERT'),'no notifications.bank_name INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.notifications','bank_name','UPDATE'),'no notifications.bank_name UPDATE');
select pg_temp.check(not has_column_privilege('authenticated','public.notifications','account_number','SELECT'),'no raw notifications.account_number SELECT');
select pg_temp.check(not has_column_privilege('authenticated','public.notifications','account_number','INSERT'),'no notifications.account_number INSERT');
select pg_temp.check(not has_column_privilege('authenticated','public.notifications','account_number','UPDATE'),'no notifications.account_number UPDATE');
select pg_temp.check(not has_column_privilege('authenticated','public.profile_private','privacy_settings','UPDATE'),'profile privacy_settings RPC-only');
select pg_temp.check(not has_column_privilege('authenticated','public.profile_private','tastes','UPDATE'),'profile tastes RPC-only');
select pg_temp.check(not has_column_privilege('authenticated','public.profile_private','privacy_revision','UPDATE'),'profile privacy_revision RPC-only');
select pg_temp.check(not has_table_privilege('service_role','public.consent_documents','INSERT') and not has_table_privilege('authenticated','public.consent_documents','INSERT') and not has_table_privilege('anon','public.consent_documents','INSERT'),'explicit consent_documents INSERT ACL');
select pg_temp.check(not has_table_privilege('service_role','public.consent_documents','UPDATE') and not has_table_privilege('authenticated','public.consent_documents','UPDATE') and not has_table_privilege('anon','public.consent_documents','UPDATE'),'explicit consent_documents UPDATE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.consent_documents','DELETE') and not has_table_privilege('authenticated','public.consent_documents','DELETE') and not has_table_privilege('anon','public.consent_documents','DELETE'),'explicit consent_documents DELETE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.terms_versions','INSERT') and not has_table_privilege('authenticated','public.terms_versions','INSERT') and not has_table_privilege('anon','public.terms_versions','INSERT'),'explicit terms_versions INSERT ACL');
select pg_temp.check(not has_table_privilege('service_role','public.terms_versions','UPDATE') and not has_table_privilege('authenticated','public.terms_versions','UPDATE') and not has_table_privilege('anon','public.terms_versions','UPDATE'),'explicit terms_versions UPDATE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.terms_versions','DELETE') and not has_table_privilege('authenticated','public.terms_versions','DELETE') and not has_table_privilege('anon','public.terms_versions','DELETE'),'explicit terms_versions DELETE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_consents','INSERT') and not has_table_privilege('authenticated','public.profile_consents','INSERT') and not has_table_privilege('anon','public.profile_consents','INSERT'),'explicit profile_consents INSERT ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_consents','UPDATE') and not has_table_privilege('authenticated','public.profile_consents','UPDATE') and not has_table_privilege('anon','public.profile_consents','UPDATE'),'explicit profile_consents UPDATE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_consents','DELETE') and not has_table_privilege('authenticated','public.profile_consents','DELETE') and not has_table_privilege('anon','public.profile_consents','DELETE'),'explicit profile_consents DELETE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_consent_states','INSERT') and not has_table_privilege('authenticated','public.profile_consent_states','INSERT') and not has_table_privilege('anon','public.profile_consent_states','INSERT'),'explicit profile_consent_states INSERT ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_consent_states','UPDATE') and not has_table_privilege('authenticated','public.profile_consent_states','UPDATE') and not has_table_privilege('anon','public.profile_consent_states','UPDATE'),'explicit profile_consent_states UPDATE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_consent_states','DELETE') and not has_table_privilege('authenticated','public.profile_consent_states','DELETE') and not has_table_privilege('anon','public.profile_consent_states','DELETE'),'explicit profile_consent_states DELETE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_health_preferences','INSERT') and not has_table_privilege('authenticated','public.profile_health_preferences','INSERT') and not has_table_privilege('anon','public.profile_health_preferences','INSERT'),'explicit profile_health_preferences INSERT ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_health_preferences','UPDATE') and not has_table_privilege('authenticated','public.profile_health_preferences','UPDATE') and not has_table_privilege('anon','public.profile_health_preferences','UPDATE'),'explicit profile_health_preferences UPDATE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_health_preferences','DELETE') and not has_table_privilege('authenticated','public.profile_health_preferences','DELETE') and not has_table_privilege('anon','public.profile_health_preferences','DELETE'),'explicit profile_health_preferences DELETE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_food_preferences','INSERT') and not has_table_privilege('authenticated','public.profile_food_preferences','INSERT') and not has_table_privilege('anon','public.profile_food_preferences','INSERT'),'explicit profile_food_preferences INSERT ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_food_preferences','UPDATE') and not has_table_privilege('authenticated','public.profile_food_preferences','UPDATE') and not has_table_privilege('anon','public.profile_food_preferences','UPDATE'),'explicit profile_food_preferences UPDATE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.profile_food_preferences','DELETE') and not has_table_privilege('authenticated','public.profile_food_preferences','DELETE') and not has_table_privilege('anon','public.profile_food_preferences','DELETE'),'explicit profile_food_preferences DELETE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.health_code_catalog','INSERT') and not has_table_privilege('authenticated','public.health_code_catalog','INSERT') and not has_table_privilege('anon','public.health_code_catalog','INSERT'),'explicit health_code_catalog INSERT ACL');
select pg_temp.check(not has_table_privilege('service_role','public.health_code_catalog','UPDATE') and not has_table_privilege('authenticated','public.health_code_catalog','UPDATE') and not has_table_privilege('anon','public.health_code_catalog','UPDATE'),'explicit health_code_catalog UPDATE ACL');
select pg_temp.check(not has_table_privilege('service_role','public.health_code_catalog','DELETE') and not has_table_privilege('authenticated','public.health_code_catalog','DELETE') and not has_table_privilege('anon','public.health_code_catalog','DELETE'),'explicit health_code_catalog DELETE ACL');
select pg_temp.check(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef and not coalesce('search_path=""'=any(p.proconfig),false)),'every SD function has empty search_path');
select pg_temp.check(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prorettype='trigger'::regtype and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE'))),'trigger EXECUTE closed');
select pg_temp.check(not has_function_privilege('anon','public.run_s1_health_retention(integer)','EXECUTE') and not has_function_privilege('authenticated','public.run_s1_health_retention(integer)','EXECUTE') and has_function_privilege('service_role','public.run_s1_health_retention(integer)','EXECUTE'),'retention only service role');
select pg_temp.check(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 's1_%' and p.prosecdef and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))),'internal SD helpers not callable');
select pg_temp.check(not has_function_privilege('authenticated','public.meeting_midpoint(uuid[],double precision,double precision)','EXECUTE'),'midpoint remains closed');
select pg_temp.check(not exists(select 1 from information_schema.role_table_grants where table_schema='private' and table_name='consent_requests' and grantee in ('anon','authenticated','service_role','PUBLIC')),'idempotency ledger private');
create table public.s1_default_acl_probe(id integer);
create function public.s1_default_acl_probe() returns integer language sql as $$select 1$$;
select pg_temp.check(not has_table_privilege('authenticated','public.s1_default_acl_probe','SELECT') and not has_table_privilege('anon','public.s1_default_acl_probe','SELECT') and not has_table_privilege('service_role','public.s1_default_acl_probe','INSERT'),'new table defaults closed');
select pg_temp.check(not has_function_privilege('anon','public.s1_default_acl_probe()','EXECUTE') and not has_function_privilege('authenticated','public.s1_default_acl_probe()','EXECUTE'),'new function defaults closed');
select pg_temp.check(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and p.prorettype<>'trigger'::regtype and p.proname not in ('get_consent_manifest','email_available') and has_function_privilege('anon',p.oid,'EXECUTE')),'anon cannot execute any data SD API');
select * from finish();
rollback;
